{
  "report_name": "weekly_engaged_projects",
  "objective": "Track weekly engagement of projects by checkout or purchase events, broken down by device, with WoW comparison and validation that engaged projects are at least as many as each subset.",
  "grain": "iso_week × device",
  "timezone": "Asia/Singapore",
  "population": {
    "include": ["projects with at least one checkout or purchase event in the ISO week"],
    "exclude": ["project_id 79 and 80 (internal)", "events with properties.device = 'bot'"]
  },
  "metrics": [
    {
      "id": "weekly_engaged_projects",
      "definition": "Number of distinct project_id with at least one checkout or purchase event in the ISO week, excluding internal projects and bot devices.",
      "formula_sql": "COUNT(DISTINCT project_id)",
      "owner": "Product Analytics"
    },
    {
      "id": "checkout_projects",
      "definition": "Number of distinct project_id with at least one checkout event in the ISO week, excluding internal projects and bot devices.",
      "formula_sql": "COUNT(DISTINCT project_id) FILTER (WHERE event_type = 'checkout')",
      "owner": "Product Analytics"
    },
    {
      "id": "purchase_projects",
      "definition": "Number of distinct project_id with at least one purchase event in the ISO week, excluding internal projects and bot devices.",
      "formula_sql": "COUNT(DISTINCT project_id) FILTER (WHERE event_type = 'purchase')",
      "owner": "Product Analytics"
    }
  ],
  "dimensions": ["iso_week", "device"],
  "filters": [
    "event_type IN ('checkout', 'purchase')",
    "project_id NOT IN (79, 80)",
    "properties.device != 'bot'"
  ],
  "comparisons": ["WoW (week-over-week) change for weekly_engaged_projects"],
  "delivery": {
    "format": "Parquet",
    "cadence": "Every Friday at 11:00 Asia/Singapore"
  },
  "assumptions": [
    "ISO week runs Monday to Sunday.",
    "Events are timestamped in UTC and converted to Asia/Singapore for week bucketing.",
    "The 'device' field is taken from properties.device.",
    "A project is considered engaged if it has at least one checkout or purchase event in the week."
  ],
  "open_questions": [
    "How to reliably join plan and customer segment to project_id? (Data engineering says not reliable; left as open question.)"
  ],
  "validation_checks": [
    "weekly_engaged_projects >= checkout_projects",
    "weekly_engaged_projects >= purchase_projects"
  ]
}
